// ================================
// สร้างข้อมูลเช็คชื่อ 1 แถว → ส่งเป็น JSON ก้อนเดียวให้โหนด Postgres บันทึก
// ★ ตัดสิน "สาย/ตรงเวลา" ด้วยเวลาเข้างานรายคน (เดิมฟิกซ์ 09:00 ทุกคน)
// ================================
function extractJson(text) {
  if (!text) return null;
  const s = String(text).trim();
  const fenced = s.match(/```json\s*([\s\S]*?)\s*```/i);
  const payload = fenced ? fenced[1].trim() : s;
  try { return JSON.parse(payload); } catch (e) {
    const obj = payload.match(/\{[\s\S]*\}/);
    if (!obj) return null;
    try { return JSON.parse(obj[0]); } catch (e2) { return null; }
  }
}
function thaiDateToISO(dateTh, yearBE) {
  if (!dateTh) return null;
  const months = {'ม.ค.':1,'ก.พ.':2,'มี.ค.':3,'เม.ย.':4,'พ.ค.':5,'มิ.ย.':6,'ก.ค.':7,'ส.ค.':8,'ก.ย.':9,'ต.ค.':10,'พ.ย.':11,'ธ.ค.':12};
  const m = String(dateTh).trim().match(/(\d{1,2})\s+([^\s]+)\s+(\d{4})?/);
  if (!m) return null;
  const dd = Number(m[1]), mm = months[m[2]] || null;
  const yyRaw = m[3] ? Number(m[3]) : Number(yearBE);
  if (!dd || !mm || !yyRaw) return null;
  const yyAD = yyRaw >= 2400 ? yyRaw - 543 : yyRaw;
  if (yyAD < 2000 || yyAD > 2100) return null;
  return `${yyAD}-${String(mm).padStart(2,'0')}-${String(dd).padStart(2,'0')}`;
}

const w = $('Parse Webhook').first().json;
const items = $input.all().map(i => i.json);
const profile = items.find(x => x.displayName) || {};
const gem = items.find(x => x?.content?.parts?.[0]?.text) || $('Analyze Check-in Image').first().json;

let emp = {};
try { emp = $('พนักงาน: userId นี้คือใคร').first().json || {}; } catch (e) { emp = {}; }
const empNick = emp['ชื่อเล่น'] || '';
const workStart = (emp['เวลาเข้างาน'] || '').trim();

let gemText = '';
if (gem?.content?.parts?.length) gemText = gem.content.parts.map(p => p.text || '').join('\n');
const ex = extractJson(gemText) || {};
const dt = ex.datetime_in_image || {};
const loc = ex.location_in_image || {};
const foundOverlay = ex.found_overlay_text === true;

// เวลาสำรองจาก "เวลาที่ข้อความเข้า LINE" (ใช้เมื่ออ่านรูปไม่ออก)
const t = new Date(new Date(w.timestamp).toLocaleString('en-US', { timeZone: 'Asia/Bangkok' }));
const pad = (n) => String(n).padStart(2, '0');
const fbTimeHMS = `${pad(t.getHours())}:${pad(t.getMinutes())}:${pad(t.getSeconds())}`;
const fbTimeHM = fbTimeHMS.slice(0, 5);

const fromImage = !!(foundOverlay && (dt.time_hm || dt.time_hms));
const timeHM = dt.time_hm || (dt.time_hms ? String(dt.time_hms).slice(0, 5) : null) || fbTimeHM;
const timeHMS = dt.time_hms || (dt.time_hm ? dt.time_hm + ':00' : null) || fbTimeHMS;
const dateISO = thaiDateToISO(dt.date_th || null, dt.year_be) || w.todayDateKey;

// ── สาย/ตรงเวลา เทียบเวลาเข้างานของคนนั้น ──
const ws = workStart.match(/^(\d{1,2})[:.](\d{2})$/);
const limitMin = ws ? Number(ws[1]) * 60 + Number(ws[2]) : 9 * 60;
const [hh, mm] = (timeHM || '').split(':').map(Number);
let status = 'abnormal', reason = '';
if (Number.isFinite(hh) && Number.isFinite(mm)) {
  const late = (hh * 60 + mm) > limitMin;
  status = late ? 'late' : 'ontime';
  reason = `${late ? 'สาย' : 'ตรงเวลา'} (${fromImage ? 'เวลาจากรูป' : 'เวลาที่ส่งเข้ากลุ่ม'} · เข้างาน ${ws ? workStart : '9:00 — ไม่มีเวลาเข้างานในทะเบียน'})`;
} else {
  reason = foundOverlay ? 'อ่านเวลาจากรูปไม่ออก' : 'ไม่พบข้อความบนรูป';
}

const fullAddress = loc.full_address || [loc.house_no, loc.road_or_route,
  loc.district ? `อ.${loc.district}` : null, loc.province ? `จ.${loc.province}` : null,
  loc.postal_code].filter(Boolean).join(' ').trim() || '';

return [{ json: {
  userId: w.userId || '',
  displayName: empNick || profile.displayName || '',
  dateIso: dateISO,
  checkinAt: (dateISO && timeHMS) ? `${dateISO}T${timeHMS}+07:00` : '',
  timeHm: timeHM || '',
  workStart: workStart,
  status, reason,
  timeSource: fromImage ? 'image' : 'message',
  fullAddress,
  province: loc.province || '',
  raw: { overlay_text_raw: ex.overlay_text_raw || '', thai_raw: dt.thai_raw || '',
         date_th: dt.date_th || '', quality: ex.quality || {}, messageId: w.messageId || '' }
}}];

