FROM v_employees
WHERE active;

parameters.jsCode:
// จับคู่ "ใครลา/สาย" จากข้อความในกลุ่ม — รายชื่อมาจากฐานข้อมูลเรา (ไม่ใช่ชีตแล้ว)
const w = $('Parse Webhook').first().json;
const rawText = (w.textContent || '').trim();
const senderUserId = w.userId;

const reportKeywords = ['ลา','หยุด','สาย','เลท','เข้าสาย','ทดเวลา','สลับ','ชดเชย','เปลี่ยนวันหยุด',
  'ติดธุระ','รถเสีย','ป่วย','ท้องเสีย','ไม่สบาย','หยุดยาว','หยุดเทศกาล','หยุดบริษัท','ลาพักร้อน',
  'หยุดนักขัตฤกษ์','วันหยุดราชการ'];
if (!reportKeywords.some(k => rawText.includes(k))) return [];

const employeeList = $input.all().map(i => i.json).filter(e => e['ชื่อเล่น']);
const employeeNames = employeeList.map(e => e['ชื่อเล่น']).join(', ');

const prompt = `คุณคือระบบจับคู่ชื่อพนักงานที่แจ้งลา/หยุด/สาย

รายชื่อพนักงานทั้งหมด: ${employeeNames}

ข้อความจากกลุ่ม LINE:
"${rawText}"

กฎสำคัญ:
1. @mention ในข้อความคือการแท็กหัวหน้า ไม่ใช่คนที่ลา → ละเว้น @mention ทั้งหมด
2. หาชื่อพนักงานที่ลา/หยุด/สายจากข้อความที่เหลือ (พิมพ์ผิด/ชื่อสั้น/bullet list ก็จับให้ได้)
3. ถ้าไม่พบชื่อพนักงานในข้อความ (นอกจาก @mention) → is_sender_self = true
4. ถ้าชื่อไม่มีในรายชื่อพนักงาน ให้ข้ามไป ห้ามเดา

ตอบเป็น JSON เท่านั้น ห้ามมีข้อความอื่น ห้ามมี markdown:
{
  "is_sender_self": false,
  "matched": [ { "nickname": "ชื่อเล่นจากรายชื่อตรงๆ", "confidence": "high|medium|low", "reason": "สั้นๆ" } ]
}`;

return [{ json: { prompt, rawText, senderUserId, employeeList } }];

// แปลงคำตอบ Gemini → แถวที่จะบันทึกหมายเหตุ (userId + note)
const aiText = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
const prep = $('Prepare Prompt').first().json;
const employeeList = prep.employeeList || [];
const senderUserId = prep.senderUserId;
const rawText = prep.rawText;

let aiResult = null;
try { aiResult = JSON.parse(aiText.replace(/```json|```/g, '').trim()); }
catch (e) { console.log('parse ไม่ได้:', aiText); return []; }

const out = [];
const pushRow = (emp) => {
  const ids = emp.line_user_ids || [];
  const uid = ids.includes(senderUserId) ? senderUserId : (ids[0] || '');
  if (!uid) { console.log('ยังไม่ผูก LINE:', emp['ชื่อเล่น']); return; }
  out.push({ json: { userId: uid, note: rawText, nickname: emp['ชื่อเล่น'] } });
};

if (aiResult.is_sender_self) {
  const me = employeeList.find(e => (e.line_user_ids || []).includes(senderUserId));
  if (me) pushRow(me);
  return out;
}
for (const m of (aiResult.matched || [])) {
  const emp = employeeList.find(e => e['ชื่อเล่น'] === m.nickname);
  if (!emp) { console.log('ไม่มีในทะเบียน:', m.nickname); continue; }
  pushRow(emp);
}
return out;
